233:     // Replacement of java.lang.Class#getResourceAsStream(String) to disable sharing the resource
234:     // stream
235:     // in multiple class loaders and specifically to avoid
236:     // https://bugs.openjdk.java.net/browse/JDK-8205976
237:     private static InputStream getResourceAsStream(String name) {
238:         // Remove leading '/' since all our resource paths include a leading directory
239:         // See:
240:         // https://github.com/openjdk/jdk/blob/master/src/java.base/share/classes/java/lang/Class.java#L3054
241:         String resolvedName = name.substring(1);
242:         ClassLoader cl = SQLiteJDBCLoader.class.getClassLoader();
243:         URL url = cl.getResource(resolvedName);
244:         if (url == null) {
245:             return null;
246:         }
247:         try {
248:             URLConnection connection = url.openConnection();
249:             connection.setUseCaches(false);
250:             return connection.getInputStream();
251:         } catch (IOException e) {
252:             logger.error(() -> "Could not connect", e);
253:             return null;
254:         }
255:     }
