257:     /**
258:      * Loads native library using the given path and name of the library.
259:      *
260:      * @param path Path of the native library.
261:      * @param name Name of the native library.
262:      * @return True for successfully loading; false otherwise.
263:      */
264:     private static boolean loadNativeLibrary(String path, String name) {
265:         File libPath = new File(path, name);
266:         if (libPath.exists()) {
267: 
268:             try {
269:                 System.load(new File(path, name).getAbsolutePath());
270:                 return true;
271:             } catch (UnsatisfiedLinkError e) {
272: 
273:                 logger.error(
274:                         () ->
275:                                 MessageFormat.format(
276:                                         "Failed to load native library: {0}. osinfo: {1}",
277:                                         name, OSInfo.getNativeLibFolderPathForCurrentOS()),
278:                         e);
279:                 return false;
280:             }
281: 
282:         } else {
283:             return false;
284:         }
285:     }
