287:     private static boolean loadNativeLibraryJdk() {
288:         try {
289:             System.loadLibrary(LibraryLoaderUtil.NATIVE_LIB_BASE_NAME);
290:             return true;
291:         } catch (UnsatisfiedLinkError e) {
292:             logger.error(() -> "Failed to load native library through System.loadLibrary", e);
293:             return false;
294:         }
295:     }
