297:     /**
298:      * Loads SQLite native library using given path and name of the library.
299:      *
300:      * @throws
301:      */
302:     private static void loadSQLiteNativeLibrary() throws Exception {
303:         if (extracted) {
304:             return;
305:         }
306: 
307:         List<String> triedPaths = new LinkedList<>();
308: 
309:         // Try loading library from org.sqlite.lib.path library path */
310:         String sqliteNativeLibraryPath = System.getProperty("org.sqlite.lib.path");
311:         String sqliteNativeLibraryName = System.getProperty("org.sqlite.lib.name");
312:         if (sqliteNativeLibraryName == null) {
313:             sqliteNativeLibraryName = LibraryLoaderUtil.getNativeLibName();
314:         }
315: 
316:         if (sqliteNativeLibraryPath != null) {
317:             if (loadNativeLibrary(sqliteNativeLibraryPath, sqliteNativeLibraryName)) {
318:                 extracted = true;
319:                 return;
320:             } else {
321:                 triedPaths.add(sqliteNativeLibraryPath);
322:             }
323:         }
324: 
325:         // Load the os-dependent library from the jar file
326:         sqliteNativeLibraryPath = LibraryLoaderUtil.getNativeLibResourcePath();
327:         boolean hasNativeLib =
328:                 LibraryLoaderUtil.hasNativeLib(sqliteNativeLibraryPath, sqliteNativeLibraryName);
329: 
330:         if (hasNativeLib) {
331:             // temporary library folder
332:             String tempFolder = getTempDir().getAbsolutePath();
333:             // Try extracting the library from jar
334:             if (extractAndLoadLibraryFile(
335:                     sqliteNativeLibraryPath, sqliteNativeLibraryName, tempFolder)) {
336:                 extracted = true;
337:                 return;
338:             } else {
339:                 triedPaths.add(sqliteNativeLibraryPath);
340:             }
341:         }
342: 
343:         // As a last resort try from java.library.path
344:         String javaLibraryPath = System.getProperty("java.library.path", "");
345:         for (String ldPath : javaLibraryPath.split(File.pathSeparator)) {
346:             if (ldPath.isEmpty()) {
347:                 continue;
348:             }
349:             if (loadNativeLibrary(ldPath, sqliteNativeLibraryName)) {
350:                 extracted = true;
351:                 return;
352:             } else {
353:                 triedPaths.add(ldPath);
354:             }
355:         }
356: 
357:         // As an ultimate last resort, try loading through System.loadLibrary
358:         if (loadNativeLibraryJdk()) {
359:             extracted = true;
360:             return;
361:         }
362: 
363:         extracted = false;
364:         throw new NativeLibraryNotFoundException(
365:                 String.format(
366:                         "No native library found for os.name=%s, os.arch=%s, paths=[%s]",
367:                         OSInfo.getOSName(),
368:                         OSInfo.getArchName(),
369:                         StringUtils.join(triedPaths, File.pathSeparator)));
370:     }
